import{_ as a,o as e,c as o,a0 as r}from"./chunks/framework.Caz7a20Z.js";const h=JSON.parse('{"title":"论文基本改完，多智能体也差不多了","description":"今天把论文基本都改完了，剩下的就是明天补上敏感性分析，然后找老师汇报；多智能体那边也差不多收尾了。轻松收工的一天。","frontmatter":{"title":"论文基本改完，多智能体也差不多了","date":"2026-08-26T00:00:00.000Z","tags":["日记"],"description":"今天把论文基本都改完了，剩下的就是明天补上敏感性分析，然后找老师汇报；多智能体那边也差不多收尾了。轻松收工的一天。"},"headers":[],"relativePath":"posts/diary-20260826.md","filePath":"posts/diary-20260826.md","lastUpdated":null}'),s={name:"posts/diary-20260826.md"};function n(i,t,p,d,l,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="论文基本改完-多智能体也差不多了" tabindex="-1">论文基本改完，多智能体也差不多了 <a class="header-anchor" href="#论文基本改完-多智能体也差不多了" aria-label="Permalink to &quot;论文基本改完，多智能体也差不多了&quot;">​</a></h1><p>今天是个&quot;收口&quot;的日子——之前欠的修改债，基本都还上了 😌。</p><h2 id="论文-改完了" tabindex="-1">论文：改完了 <a class="header-anchor" href="#论文-改完了" aria-label="Permalink to &quot;论文：改完了&quot;">​</a></h2><p>说&quot;基本改完&quot;不是客套，<strong>该改的都改了</strong>：前言、方法、结果、讨论，一轮轮过下来，整体顺了不少。比起前两天那种&quot;这儿还粗、那儿还浅&quot;的心虚，现在心里踏实多了。</p><p>剩下的就一件事：<strong>明天再加上敏感性分析（Sensitivity Analysis）</strong>。这步做完，论文正文就算真正齐活了，然后就可以<strong>找老师汇报一下</strong>进度。</p><p>想想这一路，从代码整理、到正文、到作图、到一遍遍改，终于快摸到终点线了。明天补完敏感性分析，就能跟老师交差，爽。</p><h2 id="多智能体-差不多了" tabindex="-1">多智能体：差不多了 <a class="header-anchor" href="#多智能体-差不多了" aria-label="Permalink to &quot;多智能体：差不多了&quot;">​</a></h2><p>另一边，<strong>多智能体（Multi-agent）也差不多收尾了</strong>。之前物种分布模型智能体跑通后又优化了一轮，效果上来了；整体这套多智能体的架子也搭得七七八八。</p><p>&quot;差不多&quot;的意思是：核心能跑、能出东西，剩下的是打磨和边角 case，不是伤筋动骨的大改。对一个研究生自己折腾的玩具级智能体来说，这进度我已经很满意了哈哈。</p><h2 id="就这样吧" tabindex="-1">就这样吧 <a class="header-anchor" href="#就这样吧" aria-label="Permalink to &quot;就这样吧&quot;">​</a></h2><p>今天没有硬磕新东西，主要是把存量收干净。这种&quot;眼看着清单一条条划掉&quot;的感觉，比通宵硬刚舒服太多。</p><p>明天：敏感性分析 + 找老师汇报。然后……看老师怎么说，再决定下一波活儿。</p><p>就这样吧，哈哈 😄</p>',13)])])}const _=a(s,[["render",n]]);export{h as __pageData,_ as default};
